with deduped as (select * from (select *, row_number() over (partition by order_id order by unit_price desc nulls first, id asc) as row_num from order_items) ranked where row_num = 1) select order_id, bit_or(quantity) as quantity_bit_or, stddev_samp(unit_price) as unit_price_stddev, approx_percentile(quantity, 0.95) as quantity_p95 from deduped group by order_id having approx_percentile(quantity, 0.95) < 0;
